package com.lexorion.payroll.api;
import com.lexorion.payroll.domain.*;import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.time.LocalDate;import java.util.*;
public final class CalculationDtos{private CalculationDtos(){}public record CreateCalculation(@NotNull LocalDate calculationDate,@Null String currency,@Null UUID organizationId,@Null UUID workspaceId,@Null UUID userId,@Null UUID employeeId,@Null UUID payrollEmployeeId,@Null UUID profileId,@Null UUID calculationId,@Null String role){}public record CalculationLineResponse(String componentKey,String displayName,ComponentCategory category,AmountType amountType,OccurrenceType occurrence,Taxability taxability,BigDecimal configuredValue,BigDecimal calculatedAmount,String currency){public static CalculationLineResponse from(CalculationLine l){return new CalculationLineResponse(l.getComponentKey(),l.getDisplayName(),l.getCategory(),l.getAmountType(),l.getOccurrence(),l.getTaxability(),l.getConfiguredValue(),l.getCalculatedAmount(),l.getCurrency());}}public record CalculationResponse(String employeeCode,LocalDate calculationDate,String currency,BigDecimal grossAmount,BigDecimal deductionAmount,BigDecimal netAmount,List<CalculationLineResponse>lines){public static CalculationResponse from(Calculation c){return new CalculationResponse(c.getEmployeeCode(),c.getCalculationDate(),c.getCurrency(),c.getGrossAmount(),c.getDeductionAmount(),c.getNetAmount(),c.getLines().stream().map(CalculationLineResponse::from).toList());}}}
